sysauto_script.script:
/**
 * Scheduled Job: Stale Monitored Service Check
 *
 * Finds Monitored Service records that have NOT received a Service Event
 * in the last 15 minutes and sets their status to "Unknown".
 */
(function () {
    var fifteenMinAgo = new GlideDateTime();
    fifteenMinAgo.addSeconds(-900); // 15 minutes = 900 seconds

    // Query Monitored Services whose last_checked is older than 15 min
    // or whose last_checked is empty
    var gr = new GlideRecord('x_1980074_itom_i_0_mon_svc');
    gr.addQuery('status', '!=', 'unknown');

    var qc = gr.addQuery('last_checked', '<', fifteenMinAgo.getValue());
    qc.addOrCondition('last_checked', '');

    gr.query();

    var count = 0;
    while (gr.next()) {
        gr.setValue('status', 'unknown');
        gr.update();
        count++;
    }

    if (count > 0) {
        gs.info('[ITOM Health] Marked ' + count + ' monitored service(s) as Unknown due to stale check-in.');
    } else {
        gs.debug('[ITOM Health] No stale monitored services found.');
    }
})();
